const input = require("fs").readFileSync(0, "utf8");
const tokens = input.trim().split(/\s+/);

class TreeNode {
  constructor(value, left = null, right = null) {
    this.value = value;
    this.left = left;
    this.right = right;
  }
}

function buildTree(tokens, i = 0) {
  if (i >= tokens.length || tokens[i] === "-") {
    return null;
  }
  const left = buildTree(tokens, 2 * i + 1);
  const right = buildTree(tokens, 2 * i + 2);
  return new TreeNode(Number(tokens[i]), left, right);
}

function height(node) {
  if (node === null) {
    return 0;
  }
  return 1 + Math.max(height(node.left), height(node.right));
}

function maxValue(node) {
  if (node === null) {
    return -Infinity;
  }
  return Math.max(node.value, maxValue(node.left), maxValue(node.right));
}

function countLeaves(node) {
  if (node === null) {
    return 0;
  }
  if (node.left === null && node.right === null) {
    return 1;
  }
  return countLeaves(node.left) + countLeaves(node.right);
}

function count(node) {
  if (node === null) {
    return 0;
  }
  return 1 + count(node.left) + count(node.right);
}

function sum(node) {
  if (node === null) {
    return 0;
  }
  return node.value + sum(node.left) + sum(node.right);
}

