const input = require("fs").readFileSync(0, "utf8");
const [insertLine, queryLine] = input.trim().split("\n");
const values = insertLine.trim().split(/\s+/).map(Number);
const queries = queryLine.trim().split(/\s+/).map(Number);

class TreeNode {
  constructor(value, left = null, right = null) {
    this.value = value;
    this.left = left;
    this.right = right;
  }
}

function insert(node, value) {
  if (node === null) {
    return new TreeNode(value);
  }
  if (value < node.value) {
    node.left = insert(node.left, value);
  } else if (value > node.value) {
    node.right = insert(node.right, value);
  }
  return node;
}

function contains(node, value) {
  while (node !== null) {
    if (value === node.value) {
      return true;
    }
    node = value < node.value ? node.left : node.right;
  }
  return false;
}

function minValue(node) {
  while (node.left !== null) {
    node = node.left;
  }
  return node.value;
}

function maxValue(node) {
  while (node.right !== null) {
    node = node.right;
  }
  return node.value;
}

function inorder(node, out) {
  if (node === null) {
    return;
  }
  inorder(node.left, out);
  out.push(node.value);
  inorder(node.right, out);
}

let root = null;
for (const v of values) {
  root = insert(root, v);
}
const sorted = [];
inorder(root, sorted);
console.log(`Inorder: ${sorted.join(" ")}`);
for (const q of queries) {
  console.log(`${q}: ${contains(root, q) ? "found" : "missing"}`);
}
console.log(`Min: ${minValue(root)}`);
console.log(`Max: ${maxValue(root)}`);

